 "content": "from collections import Counter


def _mode(values):
    return Counter(values).most_common(1)[0][0]


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = _mode(v for row in grid for v in row)
    row_lines = [r for r in range(h) if _mode(grid[r]) != background]
    col_lines = [c for c in range(w) if _mode(grid[r][c] for r in range(h)) != background]
    if len(row_lines) < 2 or len(col_lines) < 2:
        return [row[:] for row in grid]

    node = [[grid[r][c] for c in col_lines] for r in row_lines]
    divider = _mode(v for row in node for v in row)
    matches = []
    for r in range(len(node) - 1):
        for c in range(len(node[0]) - 1):
            a = node[r][c]
            if a != divider and node[r][c + 1] == a and node[r + 1][c] == a and node[r + 1][c + 1] == a:
                matches.append((r, c, a))
    if not matches:
        return [[background]]

    r0 = min(r for r, c, a in matches)
    r1 = max(r for r, c, a in matches)
    c0 = min(c for r, c, a in matches)
    c1 = max(c for r, c, a in matches)
    out = [[background for _ in range(c1 - c0 + 1)] for _ in range(r1 - r0 + 1)]
    for r, c, value in matches:
        out[r - r0][c - c0] = value
    return out
